package com.example.starter.greenhouse.domain;

/**
 * 气候策略生命周期状态。
 * DRAFT 编制 → VALIDATED 校验通过 → ACTIVE 生效中 → SUPERSEDED 被新策略替代。
 */
public enum StrategyStatus {
    DRAFT,
    VALIDATED,
    ACTIVE,
    SUPERSEDED
}

package com.example.starter.greenhouse.domain;

/**
 * 环控指令类型。HEATING 加热、LIGHTING 补光为耗能指令；VENTILATION 通风为零能耗指令。
 */
public enum CommandType {
    HEATING(true),
    LIGHTING(true),
    VENTILATION(false);

    private final boolean energyConsuming;

    CommandType(boolean energyConsuming) {
        this.energyConsuming = energyConsuming;
    }

    /** 是否消耗能耗预算。 */
    public boolean isEnergyConsuming() {
        return energyConsuming;
    }
}

package com.example.starter.greenhouse.domain;

/**
 * 偏差告警状态：OPEN 连续 3 点偏离触发后待确认；ACKNOWLEDGED 已以 requestId 幂等确认。
 */
public enum AlertStatus {
    OPEN,
    ACKNOWLEDGED
}

package com.example.starter.greenhouse.domain;

/**
 * 日评估状态：OPEN 可反复重算；SEALED 封存终态，重复封存幂等返回首次结果。
 */
public enum EvaluationStatus {
    OPEN,
    SEALED
}

package com.example.starter.greenhouse.domain;

/**
 * 幂等业务类型，区分 requestId 所在的业务场景（策略下发 / 告警确认）。
 */
public enum IdempotentBizType {
    STRATEGY_ACTIVATE,
    ALERT_ACKNOWLEDGE
}

package com.example.starter.greenhouse.support;

import java.time.Clock;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 可控时钟配置：业务与测试统一通过 {@link Clock} 取当前时刻（UTC），
 * 并发与时间边界测试可注入固定/偏移时钟。
 */
@Configuration
public class ClockConfig {

    @Bean
    public Clock clock() {
        return Clock.systemUTC();
