package com.example.starter.greenhouse.repo;

import java.sql.Timestamp;
import java.time.Instant;

/**
 * IdempotentRequestRepository 的响应回填方法独立存放于同包工具，
 * 便于幂等执行器“先占位、后回填响应体”。
 */
public final class IdempotentUpdates {

    private IdempotentUpdates() {
    }

    /** 业务成功后回填 HTTP 状态与响应体 JSON。 */
    public static void fillResponse(IdempotentRequestRepository repo, org.springframework.jdbc.core.JdbcTemplate jdbc,
                                    String requestId, int httpStatus, String responseBody) {
        jdbc.update("UPDATE idempotent_request SET http_status = ?, response_body = ? WHERE request_id = ?",
                httpStatus, responseBody, requestId);
    }

    static Instant now() {
        return Instant.now();
    }

    static Timestamp ts(Instant at) {
        return Timestamp.from(at);
    }
}

