        zone.setZoneCode(req.zoneCode());
        zone.setName(req.name());
        zone.setCreatedAt(Instant.now(clock));
        try {
            return zoneRepository.insert(zone);
        } catch (DuplicateKeyException e) {
            throw ApiException.conflict("分区代码已存在: " + req.zoneCode());
        }
    }
}

