    /** 读数上报：去重归位，连续 3 点偏离触发告警。 */
    @PostMapping("/readings")
    @ResponseStatus(HttpStatus.CREATED)
    public ReadingResponse ingest(@Valid @RequestBody ReadingIngestRequest req) {
        return readingService.ingest(req);
    }

