 */
public final class TableCleaner {

    private static final List<String> TABLES = List.of(
            "idempotent_request",
            "energy_command",
            "energy_budget",
            "daily_evaluation",
            "late_reading_event",
            "deviation_alert",
            "sensor_reading",
            "strategy_change_log",
